import{_ as n,C as a,o as i,c as o,E as s,a2 as r}from"./chunks/framework.BOeh4kYD.js";const p="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/01-policy-sequence.png",l="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/02-one-person-company.png",c="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/03-two-sided-market.png",d="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/04-scenario-conversion.png",u="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/05-2028-targets.png",I=JSON.parse(`{"title":"MIIT's AI SME Entrepreneurship Support Plan Explained: An AI Startup Ecosystem Is Taking Shape","description":"","frontmatter":{"title":"MIIT's AI SME Entrepreneurship Support Plan Explained: An AI Startup Ecosystem Is Taking Shape","date":"2026-09-08","language":"en","article_type":"policy-analysis","summary":"MIIT's Artificial Intelligence SME Entrepreneurship Support Plan (2026–2028) brings computing, data, scenarios, open source, capital, and support services into one framework. China's AI startup ecosystem is moving from policy direction toward organized implementation.","publication_authorized":true,"lifecycle":"Published","column":"industry-architecture","category":"daily","edition":"research-center","cover":"/assets/covers/miit-ai-sme-support-plan.png"},"headers":[],"relativePath":"en/industry/2026-09-08-miit-ai-sme-support-plan.md","filePath":"en/industry/2026-09-08-miit-ai-sme-support-plan.md","lastUpdated":1788836110000}`),h={name:"en/industry/2026-09-08-miit-ai-sme-support-plan.md"};function m(g,e,f,y,v,b){const t=a("ArticleCover");return i(),o("div",null,[s(t,{image:"/assets/covers/miit-ai-sme-support-plan.png",kicker:"Industry Architecture · Policy Analysis",title:"MIIT's AI SME Entrepreneurship Support Plan Explained: An AI Startup Ecosystem Is Taking Shape",summary:"MIIT's Artificial Intelligence SME Entrepreneurship Support Plan (2026–2028) brings computing, data, scenarios, open source, capital, and support services into one framework. China's AI startup ecosystem is moving from policy direction toward organized implementation.",version:"2026-09-08",languageHref:"/zh/industry/2026-09-08-miit-ai-sme-support-plan",languageLabel:"中文版"}),e[0]||(e[0]=r('<h1 id="miit-s-ai-sme-entrepreneurship-support-plan-explained-an-ai-startup-ecosystem-is-taking-shape" tabindex="-1">MIIT&#39;s AI SME Entrepreneurship Support Plan Explained: An AI Startup Ecosystem Is Taking Shape <a class="header-anchor" href="#miit-s-ai-sme-entrepreneurship-support-plan-explained-an-ai-startup-ecosystem-is-taking-shape" aria-label="Permalink to &quot;MIIT&#39;s AI SME Entrepreneurship Support Plan Explained: An AI Startup Ecosystem Is Taking Shape&quot;">​</a></h1><p>On September 4, 2026, the General Office of China&#39;s Ministry of Industry and Information Technology published the <a href="https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2026/art_86c400b4473849818629663a94a6d44b.html" target="_blank" rel="noreferrer">Artificial Intelligence SME Entrepreneurship Support Plan (2026–2028)</a>.</p><p>The document is numbered Gong Xin Ting Qi Ye [2026] No. 31. It was dated August 29 and sent to the authorities responsible for small and medium-sized enterprises in every province, autonomous region, municipality, city specifically designated in the state plan, and the Xinjiang Production and Construction Corps, asking them to implement it in light of local conditions.</p><p>Reading it merely as another policy that “supports AI companies” would understate its significance.</p><p>In seven pages and 15 specific measures, the plan addresses a larger question: <strong>as artificial intelligence moves from competition among a small number of model companies into broad adoption across industries, who will complete the last mile?</strong></p><p>The answer is becoming clearer. China does not intend to rely only on a few foundation-model companies or large internet platforms. The policy seeks to cultivate AI SMEs, AI-native firms, agent developers, open-source entrepreneurs, AI application service providers, and even “one-person companies” and “super individuals.” Together, they can become the capillary network that takes AI into millions of enterprises and real industrial settings.</p><p>That is the central significance of the plan.</p><hr><h2 id="_1-start-with-the-policy-sequence-not-the-subsidy-question" tabindex="-1">1. Start with the policy sequence, not the subsidy question <a class="header-anchor" href="#_1-start-with-the-policy-sequence-not-the-subsidy-question" aria-label="Permalink to &quot;1. Start with the policy sequence, not the subsidy question&quot;">​</a></h2><p>The meaning of an industrial policy often becomes clear only when it is placed in sequence with the policies around it.</p><p>In August 2025, the State Council issued its opinion on deepening the “AI Plus” initiative. It set a target for adoption of next-generation intelligent terminals and agents to exceed 70% by 2027 and 90% by 2030. The question was no longer whether China should develop AI, but how AI would enter science, industry, consumption, public services, and governance at scale.</p><p>The 15th Five-Year Plan then placed AI Plus inside a broader national framework for digital and intelligent development. It called for progress in multimodal AI, agents, embodied intelligence, and collective intelligence; encouraged AI-native businesses; proposed national pilot-scale bases for AI applications; and called for stronger digital enablement services for SMEs and a more developed open-source ecosystem.</p><p>Beginning in spring 2026, MIIT policy moved visibly into implementation.</p><p>In April, a program for inclusive computing sought to make computing resources easier and cheaper for SMEs to access. It referred to the China Computing Network Platform, SME service zones, “computing banks,” “computing supermarkets,” and vouchers for computing, storage, and network transport.</p><p>In July, an updated guide for small, fast, lightweight, and precise digital products defined the kinds of tools suitable for SMEs: affordable products that can be deployed quickly and solve specific problems, rather than large systems by default.</p><p>On August 31, MIIT published Document No. 414, a special action to cultivate AI application service providers. It set goals for a national provider pool of more than 2,000 by the end of 2026 and no fewer than 3,000 by the end of 2027. That policy asks who will consult, implement, operate, and govern enterprise AI.</p><p>On September 3, ten departments jointly issued the SME Development Plan for the 15th Five-Year period, bringing AI entrepreneurship, transformation, management, and services into the five-year SME policy framework. One day later, the AI SME Entrepreneurship Support Plan was published.</p><p>Together, the sequence is coherent:</p><blockquote><p>Set national AI Plus goals → build computing infrastructure → cultivate SME-ready AI products → develop application service providers → expand the supply of AI startups → connect that supply with the needs of millions of SMEs.</p></blockquote><p>The new plan is therefore not an isolated policy. <strong>It is building the entrepreneurial supply layer for China&#39;s AI application economy.</strong></p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/01-policy-sequence.png"><img src="'+p+'" alt="From national strategy to a startup supply layer"></a></p><p><em>Figure 1. Five policy moves progress from strategy, infrastructure, products, and delivery to the cultivation of startups. Select the image to view it at full size.</em></p><hr><h2 id="_2-the-important-change-policy-now-discusses-one-person-companies-and-super-individuals" tabindex="-1">2. The important change: policy now discusses one-person companies and super individuals <a class="header-anchor" href="#_2-the-important-change-policy-now-discusses-one-person-companies-and-super-individuals" aria-label="Permalink to &quot;2. The important change: policy now discusses one-person companies and super individuals&quot;">​</a></h2><p>The most widely repeated sentence in the plan may be this:</p><blockquote><p>Local authorities are encouraged to provide inclusive support for micro-entities such as “one-person companies” and super individuals that use intelligent tools for agile entrepreneurship.</p></blockquote><p>It is immediately followed by another statement:</p><blockquote><p>Accelerate the cultivation of AI-native enterprises and support emerging groups, including core contributors to open-source communities and agent developers, in exploring paths to commercialization.</p></blockquote><p>These statements do not create a new business-registration category called a “one-person company,” nor do they mean that anyone using AI automatically qualifies for a subsidy. Their deeper meaning is that <strong>national policy is beginning to recognize that AI changes the smallest viable unit of enterprise formation.</strong></p><p>In the past, starting a software business usually required a product manager, developers, designers, marketing, customer service, and operations. Today, one person who can use large models, agents, and automation effectively can theoretically mobilize capabilities that once required a small team.</p><p>The key idea is not the literal number of people. It is that <strong>one person may now work with a digital production team built from AI.</strong></p><p>This is why the plan places one-person companies alongside AI-native firms, core open-source contributors, and agent developers. Its concept of an AI startup is no longer limited to a conventional software firm with an office, dozens of employees, and a complete organizational chart. Very small organizations may possess substantial capacity for knowledge work, software development, and service delivery.</p><p>AI-driven organizational productivity has entered national SME entrepreneurship policy in a direct and visible form.</p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/02-one-person-company.png"><img src="'+l+'" alt="A one-person company and an AI production team"></a></p><p><em>Figure 2. A one-person company&#39;s significance lies in expanding what one founder can produce with AI, while goals, judgment, and responsibility remain human.</em></p><hr><h2 id="_3-naming-agent-developers-turns-agent-from-a-feature-into-an-industrial-role" tabindex="-1">3. Naming agent developers turns Agent from a feature into an industrial role <a class="header-anchor" href="#_3-naming-agent-developers-turns-agent-from-a-feature-into-an-industrial-role" aria-label="Permalink to &quot;3. Naming agent developers turns Agent from a feature into an industrial role&quot;">​</a></h2><p>The words “agent developers” deserve particular attention.</p><p>The State Council&#39;s AI Plus policy already identified agents as a major form of intelligent application and set adoption targets for 2027 and 2030. MIIT now includes agent developers in a policy for cultivating entrepreneurial actors.</p><p>The first policy answers whether agents will become an important application form. The second begins to answer who will create them.</p><p>Together, they suggest that Agent is moving beyond a feature offered by model vendors and into an independent industrial ecosystem. One group supplies models; another supplies computing; others build agent tools and frameworks, create industry agents, deliver them to enterprises, and operate, govern, secure, and audit them after deployment.</p><p>This is also why Document No. 414 and the September 4 plan should be read together. Document No. 414 develops a delivery workforce of AI application service providers. The new plan expands the supply of innovative AI ventures. One addresses delivery; the other addresses entrepreneurship and innovation.</p><p>China is organizing more than a large-model industry. It is forming a service chain around the application of AI.</p><hr><h2 id="_4-the-policy-builds-both-ai-supply-and-sme-demand" tabindex="-1">4. The policy builds both AI supply and SME demand <a class="header-anchor" href="#_4-the-policy-builds-both-ai-supply-and-sme-demand" aria-label="Permalink to &quot;4. The policy builds both AI supply and SME demand&quot;">​</a></h2><p>An easy-to-miss sentence near the beginning defines the plan&#39;s economic structure: it seeks to combine innovation by AI SMEs with the use of AI to support the high-quality development of SMEs more broadly.</p><p>On one side are <strong>AI SMEs</strong>. They need markets, computing resources, data, finance, and real application settings.</p><p>On the other side are <strong>China&#39;s very large number of ordinary SMEs</strong>. They need AI to reduce cost, improve productivity, and strengthen R&amp;D, production, sales, and management.</p><p>The policy seeks to connect the two.</p><p>It calls for a group of small, fast, lightweight, and precise AI solutions for core business fields such as management, manufacturing, and R&amp;D. It also calls for a virtuous cycle between SMEs exploring AI applications and AI SMEs pursuing innovation.</p><p>This means that one of the largest AI markets may not be consumers buying one more chatbot subscription. It may be millions of SMEs purchasing modestly priced, narrowly scoped products and digital workers that solve operating problems directly: procurement assistants, sales agents, customer-service agents, R&amp;D assistants, quality analysis, document processing, market intelligence, finance support, knowledge management, and supply-chain analysis.</p><p>A large enterprise may procure a digitalization project worth tens of millions of yuan. A small manufacturer will not. It may, however, pay thousands or tens of thousands of yuan per month for a few AI systems that actually work inside its processes. At sufficient scale, this becomes a market very different from traditional enterprise software.</p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/03-two-sided-market.png"><img src="'+c+'" alt="AI supply and SME demand form a two-sided market"></a></p><p><em>Figure 3. AI ventures provide focused products, while real SME needs drive those products toward maturity.</em></p><hr><h2 id="_5-the-hardest-startup-problem-is-not-technology-but-the-first-customer" tabindex="-1">5. The hardest startup problem is not technology, but the first customer <a class="header-anchor" href="#_5-the-hardest-startup-problem-is-not-technology-but-the-first-customer" aria-label="Permalink to &quot;5. The hardest startup problem is not technology, but the first customer&quot;">​</a></h2><p>China does not lack people able to build AI products. The harder question is: <strong>once a product exists, who will let the startup test it in a real setting?</strong></p><p>In manufacturing, medicine, materials, and other industries, data, processes, and test environments are usually controlled by incumbent organizations. A technically capable startup may still lack real data, a representative environment, industry customers, and any opportunity to prove its product.</p><p>The plan therefore devotes considerable attention to application scenarios. Through activities connecting large and small enterprises and campaigns for AI-enabled industrialization, it asks leading enterprises to open settings for <strong>experimental validation, demonstration applications, and scaled commercial use</strong>. It also proposes selecting “AI entrepreneurship scenario partners” that can help startups identify scenarios, analyze needs, conduct pilots, and promote adoption.</p><p>The three stages matter:</p><p><strong>Experimental validation → demonstration application → scaled commercial use.</strong></p><p>This is more than holding another startup competition. It attempts to create a route into the market.</p><p>The plan also says that incubators should move beyond providing inexpensive office space. Computing, industry data, and application scenarios should become core services. For an AI startup, these resources may be more valuable than a low-rent office. The practical questions are whether it can obtain a model, computing, real data, a customer willing to run a test, and eventually a first order.</p><p>Entrepreneurship support is being redefined around those constraints.</p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/04-scenario-conversion.png"><img src="'+d+'" alt="From validation to scaled commercial use"></a></p><p><em>Figure 4. The plan tries to turn real application settings into a market-entry route: validation, demonstration, and scaled commercial use.</em></p><hr><h2 id="_6-open-source-is-becoming-infrastructure-for-ai-entrepreneurship" tabindex="-1">6. Open source is becoming infrastructure for AI entrepreneurship <a class="header-anchor" href="#_6-open-source-is-becoming-infrastructure-for-ai-entrepreneurship" aria-label="Permalink to &quot;6. Open source is becoming infrastructure for AI entrepreneurship&quot;">​</a></h2><p>The plan makes “deepening open-source ecosystem enablement” one of its four major work areas.</p><p>It calls for support for a national AI open-source community; contributions of models, tools, and datasets; adoption of open foundation models, development frameworks, toolchains, and datasets; services for model selection, fine-tuning, performance evaluation, and inference deployment; software, vertical models, and industry solutions built on open-source results; and mechanisms for commercializing those results.</p><p>The emerging policy judgment is clear: <strong>not every AI startup should rebuild a foundation model from scratch.</strong></p><p>A more sustainable industrial structure has a small number of companies investing heavily in foundation models and infrastructure, with many more firms using open models, tools, and data to build engineering systems, products, agents, and industry applications. Mature foundation models lower the entry threshold above them. Richer open-source resources let small companies enter the market faster.</p><p>Open source is therefore no longer treated only as a way to develop software. It is beginning to act as public infrastructure for an industry.</p><hr><h2 id="_7-a-new-signal-open-source-stars-enter-the-government-s-view-of-company-discovery" tabindex="-1">7. A new signal: open-source stars enter the government&#39;s view of company discovery <a class="header-anchor" href="#_7-a-new-signal-open-source-stars-enter-the-government-s-view-of-company-discovery" aria-label="Permalink to &quot;7. A new signal: open-source stars enter the government&#39;s view of company discovery&quot;">​</a></h2><p>The final part of the plan contains a detail that technical entrepreneurs should not overlook. It asks SME authorities to use AI and big-data analysis, together with indicators such as leading talent, invention patents, highly cited papers, and <strong>the number of stars on open-source projects</strong>, to identify high-growth-potential companies proactively.</p><p>Two phrases matter.</p><p>The first is <strong>open-source project stars</strong>. Observable influence on communities such as GitHub and AtomGit now appears directly in policy language about identifying growth companies.</p><p>The second is <strong>proactive identification</strong>. The traditional route into a government cultivation program required an enterprise to find a notice, prepare documents, submit an application, and wait for evaluation. The new wording suggests that public service systems may increasingly use publicly available signals to discover promising firms.</p><p>Patents, papers, talent, and open-source projects are all signals. This does not mean that a high GitHub star count automatically makes a company a specialized and innovative enterprise, or that stars lead directly to subsidies. It means that open-source influence now has formal visibility in policy.</p><p>This matters for software, development-tool, agent, and infrastructure startups that may have low early revenue, few employees, and little fixed capital. Traditional industrial metrics can miss them. Code contribution, project influence, and developer ecosystems may reveal their technical value earlier.</p><hr><h2 id="_8-the-plan-gives-specific-three-year-targets" tabindex="-1">8. The plan gives specific three-year targets <a class="header-anchor" href="#_8-the-plan-gives-specific-three-year-targets" aria-label="Permalink to &quot;8. The plan gives specific three-year targets&quot;">​</a></h2><p>By 2028, the plan aims to:</p><ul><li>cultivate more than <strong>10,000 new technology-oriented and innovative SMEs</strong>;</li><li>bring the number of specialized and innovative “Little Giant” enterprises in AI to <strong>more than 2,000</strong>;</li><li>establish <strong>10 high-standard technology business incubators</strong>;</li><li>establish <strong>10 national SME public service demonstration platforms or bases</strong>; and</li><li>cultivate <strong>10 national-level distinctive SME industry clusters</strong>.</li></ul><p>For context, MIIT has reported that since the beginning of the 14th Five-Year period China has cultivated approximately 17,600 Little Giant firms, more than 140,000 specialized and innovative SMEs, and more than 600,000 technology-oriented and innovative SMEs.</p><p>Setting a separate target of more than 2,000 Little Giant firms in AI is therefore not merely a headcount target. It places AI inside the national ladder for cultivating high-quality SMEs.</p><p>Nor does the policy expect these companies to remain small startups forever. Its intended progression is explicit:</p><p><strong>Entrepreneurial entity → technology-oriented and innovative SME → specialized and innovative SME → Little Giant → gazelle and unicorn.</strong></p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/en/05-2028-targets.png"><img src="'+u+'" alt="2028 targets and the AI company growth ladder"></a></p><p><em>Figure 5. The three-year quantitative targets sit alongside a growth ladder from startup entities to gazelles and unicorns.</em></p><hr><h2 id="_9-support-is-moving-beyond-a-single-fiscal-subsidy" tabindex="-1">9. Support is moving beyond a single fiscal subsidy <a class="header-anchor" href="#_9-support-is-moving-beyond-a-single-fiscal-subsidy" aria-label="Permalink to &quot;9. Support is moving beyond a single fiscal subsidy&quot;">​</a></h2><p>The plan calls for a guiding role from the National SME Development Fund, the National AI Industry Investment Fund, and the National Integrated Circuit Industry Investment Fund. It also seeks to mobilize private capital across seed, startup, and growth stages.</p><p>More unusually, it proposes exploring <strong>computing contributions as equity, data contributions as equity, and investment-incubation coordination</strong>.</p><p>AI companies have a different cost structure from many traditional firms. Their largest costs may be tokens, GPUs, data, model invocation, testing environments, and access to industry scenarios rather than land and factories. Policy support must therefore address different productive inputs.</p><p>For an early AI venture, RMB 500,000 of computing resources, a high-quality industry dataset, six months in a real operating environment provided by a large enterprise, and seed capital may be more useful than conventional support tied to physical premises. The evolution of policy instruments follows the evolution of the industry itself.</p><hr><h2 id="_10-why-cultivate-ai-smes-when-large-technology-companies-already-invest-heavily" tabindex="-1">10. Why cultivate AI SMEs when large technology companies already invest heavily? <a class="header-anchor" href="#_10-why-cultivate-ai-smes-when-large-technology-companies-already-invest-heavily" aria-label="Permalink to &quot;10. Why cultivate AI SMEs when large technology companies already invest heavily?&quot;">​</a></h2><p>Foundation models cannot solve every industry&#39;s last-mile problem.</p><p>China combines a comprehensive industrial system with an enormous number of SMEs. Bringing AI into those organizations requires detailed knowledge: how an automotive-parts firm conducts quality inspection, how a chemical company procures materials, how an export business manages customers, how a machinery factory quotes work, how a logistics firm schedules shifts, or how a materials company reviews R&amp;D literature.</p><p>A handful of foundation-model firms cannot solve all of these problems. Thousands of companies must experiment across narrow sectors.</p><p>That is the role of SMEs. They do not compete mainly on foundation-model scale. They compete through <strong>scenario innovation and business-model innovation</strong>.</p><p>The intended structure may therefore be:</p><ul><li>foundation-model companies provide the base;</li><li>computing and data infrastructure provide shared resources;</li><li>large numbers of AI startups create products;</li><li>AI application service providers complete delivery; and</li><li>millions of SMEs become the application market.</li></ul><p>That is the industrial structure required for AI Plus to reach broad adoption.</p><hr><h2 id="_11-for-agent-entrepreneurs-the-opportunity-is-unlikely-to-be-another-chatbot" tabindex="-1">11. For Agent entrepreneurs, the opportunity is unlikely to be another chatbot <a class="header-anchor" href="#_11-for-agent-entrepreneurs-the-opportunity-is-unlikely-to-be-another-chatbot" aria-label="Permalink to &quot;11. For Agent entrepreneurs, the opportunity is unlikely to be another chatbot&quot;">​</a></h2><p>From an entrepreneur&#39;s perspective, the plan increasingly favors products that can enter real industrial processes, keep working, be deployed and delivered, support continuing operations, and meet governance requirements. It does not reward an AI demo merely for existing.</p><p>This explains why the same document discusses agents, SME-ready products, industry applications, service providers, data, computing, security, compliance, intellectual property, scenarios, open source, and financing. Together, they form an AI production system.</p><p>For infrastructure such as CodeFlowMu and FCoP, the policy direction also points toward a market question. Once enterprises deploy digital workers, attention moves from “How intelligent is the model?” to “How does this digital worker keep operating?”</p><p>Does it have an identity and defined responsibilities? Which tools can it invoke, and who authorizes those invocations? How are errors recovered? How do multiple agents coordinate? How is the process audited? Who accepts the result? How are enterprise data and permissions protected?</p><p>Foundation models do not automatically solve these questions. As models mature and agents enter enterprises, the importance of infrastructure for agent operations, coordination, governance, audit, and security is likely to rise.</p><p>This remains an analysis of policy direction and industrial structure. It does not mean that any particular project has been included in a national support program. Application conditions, evaluation standards, and local implementation still depend on subsequent formal rules.</p><hr><h2 id="_12-the-main-development-is-an-industry-being-organized-not-a-single-subsidy" tabindex="-1">12. The main development is an industry being organized, not a single subsidy <a class="header-anchor" href="#_12-the-main-development-is-an-industry-being-organized-not-a-single-subsidy" aria-label="Permalink to &quot;12. The main development is an industry being organized, not a single subsidy&quot;">​</a></h2><p>The easiest question to ask is how much money the state will provide each AI startup. The plan does not answer that question. It is not a specific subsidy application notice and provides no uniform grant amount.</p><p>Its larger purpose is to organize an AI entrepreneurship ecosystem: where computing comes from, how data is opened, who supplies real scenarios, which new entrepreneurial actors are recognized, how agent developers and open-source contributors commercialize their work, who delivers products, how capital participates, how compliance is handled, and how public services discover promising companies that are not yet well known.</p><p>The plan describes its objective as a <strong>“tropical rainforest” ecosystem for entrepreneurship and innovation</strong>. A rainforest is not a single giant tree. It contains large and small organisms occupying different layers and supporting one another.</p><p>China already has large model companies, internet platforms, telecommunications operators, and computing infrastructure. The next wave may consist of small, specialized firms close to industry sites. Some will have only a few people. Some may have one person supported by many agents.</p><hr><h2 id="conclusion-from-the-large-model-race-to-adoption-across-millions-of-enterprises" tabindex="-1">Conclusion: from the large-model race to adoption across millions of enterprises <a class="header-anchor" href="#conclusion-from-the-large-model-race-to-adoption-across-millions-of-enterprises" aria-label="Permalink to &quot;Conclusion: from the large-model race to adoption across millions of enterprises&quot;">​</a></h2><p>For several years, AI competition was often judged by model parameters, benchmark scores, financing, and GPU holdings. These remain important, but the direction of national policy is changing.</p><p>The State Council established AI Plus in 2025. The 15th Five-Year Plan placed AI on the main path of economic and social digital development. Computing, open source, SME-ready products, application service providers, agent developers, and AI startups are now being organized one by one.</p><p>China&#39;s AI industry is entering a second stage: <strong>from asking who can build the model to asking who can bring AI into every industry.</strong></p><p>The scale of that stage will depend not only on a few dozen large model companies, but also on thousands of application service providers, more than ten thousand AI startups, hundreds of thousands of developers, and millions of SMEs that may use their products.</p><p>The plan does more than repeat that AI matters. It begins to answer a practical question: <strong>how can ordinary entrepreneurs, developers, and SMEs become active participants in the AI economy?</strong></p><p>Terms that rarely appeared in national industrial policy—one-person companies, super individuals, AI-native enterprises, agent developers, and open-source project star counts—now appear in an official ministerial plan. That change may matter more than any single subsidy.</p><hr><h2 id="principal-sources-and-interpretation" tabindex="-1">Principal sources and interpretation <a class="header-anchor" href="#principal-sources-and-interpretation" aria-label="Permalink to &quot;Principal sources and interpretation&quot;">​</a></h2><ul><li><a href="https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2026/art_86c400b4473849818629663a94a6d44b.html" target="_blank" rel="noreferrer">MIIT notice issuing the Artificial Intelligence SME Entrepreneurship Support Plan (2026–2028)</a></li><li><a href="https://www.miit.gov.cn/jgsj/txs/wjfb/art/2026/art_e5c990d4ec924dbc9da5818da97940ac.html" target="_blank" rel="noreferrer">MIIT special action on inclusive computing for SMEs</a></li><li><a href="https://www.miit.gov.cn/jgsj/qyj/gzdt/art/2026/art_7d898f9702124499aa651da5c9c4d66f.html" target="_blank" rel="noreferrer">MIIT explanation of the SME Development Plan for the 15th Five-Year period</a></li></ul><p>Industry implications and stage forecasts in this article are analytical judgments based on public policy documents. They are not commitments regarding eligibility or funding. Actual conditions, timing, and local implementation should be determined from subsequent formal notices.</p>',132))])}const A=n(h,[["render",m]]);export{I as __pageData,A as default};
